/**
 * Property Deals (OpsAPI plugin) — typed client for the dashboard pages.
 *
 * Shapes come from the plugin's OpenAPI (types/property-deals.generated.ts, generated by
 * @opsapi/client's generator — `npm run sync:property-deals-types`). Requests go through the
 * dashboard's apiClient, so auth, the workspace headers, token refresh and the offline queue
 * all apply. Contract: docs/property-deals/API.md.
 */
