export interface Envelope<T> {
  success: boolean;
  data: T;
  meta?: { page?: number; per_page?: number; total?: number; total_pages?: number; [k: string]: unknown };
}

export interface PdError {
  status: number;
  message: string;
  details?: unknown;
  code?: string;
}

const BASE = '/api/v2/property-deals';
const JSON_HDR = { headers: { 'Content-Type': 'application/json' } };

/** Turn any request error into { status, message, details } for toasts and inline errors. */
export function pdError(e: unknown): PdError {
  if (e instanceof AxiosError) {
    const body = (e.response?.data ?? {}) as { error?: unknown; message?: string; details?: unknown; code?: string };
    const err = body.error;
    const message =
      typeof err === 'string'
        ? err
        : (err as { message?: string } | undefined)?.message || body.message || e.message;
    return { status: e.response?.status ?? 0, message, details: body.details, code: body.code };
  }
  return { status: 0, message: e instanceof Error ? e.message : String(e) };
}

/** A readable one-liner, including field errors (details: { field: message } or a list). */
export function pdErrorText(e: unknown): string {
  const err = pdError(e);
  const d = err.details;
  if (d && typeof d === 'object' && !Array.isArray(d)) {
    const parts = Object.entries(d as Record<string, unknown>)
      .filter(([, v]) => typeof v === 'string')
      .map(([k, v]) => `${k}: ${v}`);
    if (parts.length) return `${err.message} — ${parts.join('; ')}`;
  }
  if (Array.isArray(d) && d.length && typeof d[0] === 'string') return `${err.message} — ${d.slice(0, 3).join('; ')}`;
  return err.message;
}

function qs(params?: Record<string, unknown>): string {
  if (!params) return '';
  const clean: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== null && v !== '') clean[k] = v;
  const q = buildQueryString(clean);
  return q ? (q.startsWith('?') ? q : `?${q}`) : '';
}

async function get<T>(path: string, params?: Record<string, unknown>): Promise<Envelope<T>> {
  return (await apiClient.get<Envelope<T>>(BASE + path + qs(params))).data;
}
async function send<T>(method: 'post' | 'put' | 'delete', path: string, body?: unknown): Promise<Envelope<T>> {
  if (method === 'delete') return (await apiClient.delete<Envelope<T>>(BASE + path)).data;
  return (await apiClient[method]<Envelope<T>>(BASE + path, body ?? {}, JSON_HDR)).data;
}
async function core<T>(method: 'get' | 'post' | 'put' | 'delete', path: string, body?: unknown): Promise<Envelope<T>> {
  if (method === 'get' || method === 'delete') return (await apiClient[method]<Envelope<T>>(path)).data;
  return (await apiClient[method]<Envelope<T>>(path, body ?? {}, JSON_HDR)).data;
}

